622	Status OpsRunner::RunAllKernel(RunnerVariantPack &runnerVariantPack)
623	{
624	    ATB_LOG(DEBUG) << GetLogPrefix() << " start run all kernel, kernel count:" << kernelGraph_.nodes.size();
625	    aclrtStream stream = GetExecuteStream(runnerVariantPack.context);
626	    for (size_t nodeId = 0; nodeId < kernelGraph_.nodes.size(); ++nodeId) {
627	        KernelGraphNode &node = kernelGraph_.nodes.at(nodeId);
628	        if (runnerVariantPack.mstxMemRegister != nullptr) {
629	            runnerVariantPack.mstxMemRegister->ClearMstxMemRegions();
630	            if (runnerVariantPack.workspaceBufferSize != 0) {
631	                runnerVariantPack.workspaceBufferSize = static_cast<uint64_t>(TensorUtil::AlignInt(runnerVariantPack.workspaceBufferSize, ALIGN_INT));
632	                runnerVariantPack.mstxMemRegister->AddTensorMemRegions(runnerVariantPack.workspaceBuffer, runnerVariantPack.workspaceBufferSize);
633	            }
634	            auto &inTensors = node.impl->GetInTensors();
635	            const uint64_t inTensorsSize = inTensors.size();
636	            for (uint64_t tensorId = 0; tensorId < inTensorsSize; tensorId++) {
637	                Mki::Tensor &tensor = inTensors.at(tensorId);
638	                if (node.inTensorsType.at(tensorId) == TensorType::INTERMEDIATE_TENSOR) {
639	                    tensor.data = runnerVariantPack.intermediateBuffer + reinterpret_cast<uint64_t>(node.inTensors.at(tensorId)->data);
640	                    runnerVariantPack.mstxMemRegister->AddTensorMemRegions(tensor.data, static_cast<uint64_t>(TensorUtil::AlignInt(tensor.dataSize, ALIGN_INT)));
641	                }
642	            }
643	            auto &outTensors = node.impl->GetOutTensors();
644	            const uint64_t outTensorsSize = outTensors.size();
645	            for (uint64_t tensorId = 0; tensorId < outTensorsSize; tensorId++) {
646	                Mki::Tensor &tensor = outTensors.at(tensorId);
647	                if (node.outTensorsType.at(tensorId) == TensorType::INTERMEDIATE_TENSOR) {
648	                    tensor.data = runnerVariantPack.intermediateBuffer + reinterpret_cast<uint64_t>(node.outTensors.at(tensorId)->data);
649	                    runnerVariantPack.mstxMemRegister->AddTensorMemRegions(tensor.data, static_cast<uint64_t>(TensorUtil::AlignInt(tensor.dataSize, ALIGN_INT)));
650	                }
651	            }
652	            if (static_cast<bool>(runnerVariantPack.mstxMemRegister->CheckTensorRange())) {
653	                runnerVariantPack.mstxMemRegister->MstxMemRegionsRegister();
654	            }
